window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-74697add00bd3b69"]={"versions": [{"id": "FIG-74697add00bd3b69", "releases": ["R1.3.0", "R1.5.1", "R17-03_R1.1.0", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Interaktionsdiagramm für das Logging- und Tracing-Protokoll (AUTOSAR PRS LogAndTraceProtocol). Das Diagramm stellt die Laufzeitkonfiguration von Filter- bzw. Loglevel-Einstellungen von einem externen Diagnose-/Logging-Tool (Laptop) in Richtung eines Steuergeräts (ECU) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Laptop (externer Host / DLT-Client):</strong> Sendet Konfigurationskommandos zur Anpassung des Loglevels an das Steuergerät.\n</li><li><strong>ECU (Steuergerät):</strong> Umfasst die laufenden Applikationen und die Basisinfrastruktur.\n<ul class=\"fig-list\"><li><strong>DLT (Diagnostic Log and Trace):</strong> Zentrales DLT-Modul innerhalb der ECU zur Entgegennahme von Steuerbefehlen, Verwaltung von Filterkonfigurationen und Weitergabe von Filteränderungen.\n</li><li><strong>Runtime Environment:</strong> Zwischenschicht zwischen DLT und den Anwendungsinstanzen.\n</li><li><strong>Application (dreifach dargestellt):</strong> Softwarekomponenten auf der ECU, die Logmeldungen erzeugen und über Filteränderungen informiert werden.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Interaktionen:</strong>\n<ul class=\"fig-list\"><li>Externer Kanal vom Client zum DLT-Modul (<code>Set LogLevel</code>).\n</li><li>DLT-interne Konfiguration (<code>Configuration of Filter setting</code>).\n</li><li>ECU-interner Kanal (<code>LogMessage</code>) vom DLT über die Runtime Environment zu einer Zielapplikation (<code>Inform Application about new filter setting</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Schritt 1:</strong> Der externe Client initiiert die Neukonfiguration über die Anweisung <code>Set LogLevel</code> an das DLT-Modul auf der ECU.\n</li><li><strong>Schritt 2:</strong> Das DLT-Modul führt intern die Konfiguration der Filtereinstellungen durch (<code>Configuration of Filter setting</code>).\n</li><li><strong>Schritt 3:</strong> Das DLT-Modul informiert die betroffene Applikation über die Runtime Environment bezüglich der neuen Filtereinstellung (<code>Inform Application about new filter setting</code>, Schnittstellenpfad <code>LogMessage</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die Interaktion zur dynamischen Filteranpassung während der Laufzeit: Filterkriterien werden nicht nur im zentralen DLT-Puffer/Modul ausgewertet, sondern aktiv an die Applikationen propagiert, um das Erzeugen unbenötigter Logmeldungen bereits an der Quelle zu unterdrücken.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-45bc866595cf9e4f", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Interaktionsdiagramm für das Logging- und Tracing-Protokoll (AUTOSAR PRS LogAndTraceProtocol). Das Diagramm stellt die Laufzeitkonfiguration von Filter- bzw. Loglevel-Einstellungen von einem externen Diagnose-/Logging-Tool (Laptop) in Richtung eines Steuergeräts (ECU) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Laptop (externer Host / DLT-Client):</strong> Sendet Konfigurationskommandos zur Anpassung des Loglevels an das Steuergerät.\n</li><li><strong>ECU (Steuergerät):</strong> Umfasst die laufenden Applikationen und die Basisinfrastruktur.\n<ul class=\"fig-list\"><li><strong>DLT (Diagnostic Log and Trace):</strong> Zentrales DLT-Modul innerhalb der ECU zur Entgegennahme von Steuerbefehlen, Verwaltung von Filterkonfigurationen und Weitergabe von Filteränderungen.\n</li><li><strong>Runtime Environment:</strong> Zwischenschicht zwischen DLT und den Anwendungsinstanzen.\n</li><li><strong>Application (dreifach dargestellt):</strong> Softwarekomponenten auf der ECU, die Logmeldungen erzeugen und über Filteränderungen informiert werden.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Interaktionen:</strong>\n<ul class=\"fig-list\"><li>Externer Kanal vom Client zum DLT-Modul (<code>Set LogLevel</code>).\n</li><li>DLT-interne Konfiguration (<code>Configuration of Filter setting</code>).\n</li><li>ECU-interner Kanal (<code>LogMessage</code>) vom DLT über die Runtime Environment zu einer Zielapplikation (<code>Inform Application about new filter setting</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Schritt 1:</strong> Der externe Client initiiert die Neukonfiguration über die Anweisung <code>Set LogLevel</code> an das DLT-Modul auf der ECU.\n</li><li><strong>Schritt 2:</strong> Das DLT-Modul führt intern die Konfiguration der Filtereinstellungen durch (<code>Configuration of Filter setting</code>).\n</li><li><strong>Schritt 3:</strong> Das DLT-Modul informiert die betroffene Applikation über die Runtime Environment bezüglich der neuen Filtereinstellung (<code>Inform Application about new filter setting</code>, Schnittstellenpfad <code>LogMessage</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm verdeutlicht die Interaktion zur dynamischen Filteranpassung während der Laufzeit: Filterkriterien werden nicht nur im zentralen DLT-Puffer/Modul ausgewertet, sondern aktiv an die Applikationen propagiert, um das Erzeugen unbenötigter Logmeldungen bereits an der Quelle zu unterdrücken.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-bb738c097eab79af", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Interaktionsdiagramm für das Diagnostic Log and Trace Protokoll, gültig gleichermaßen für AUTOSAR Classic und Adaptive Platform. Das Diagramm illustriert den durchgängigen Ablauf einer dynamischen Laufzeitkonfiguration von Filter- und Loglevel-Parametern von einem externen DLT-Client hin zu ECU-Applikationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Laptop (DLT-Client / Tool):</strong> Externe Logging- und Diagnosekonsole zur Initiierung von Loglevel-Änderungen.\n</li><li><strong>ECU (Steuergerät):</strong> Beherbergt Applikationen und das zentrale Log-Subsystem.\n<ul class=\"fig-list\"><li><strong>Dlt module (DLT or ara::log):</strong> Zentrales Logging-Modul der Plattform (Classic DLT oder Adaptive ara::log), zuständig für die Verarbeitung von Dlt-Steuernachrichten und die Aktualisierung der Filterzustände.\n</li><li><strong>Application (dreifach dargestellt):</strong> Anwendungs- bzw. Prozessinstanzen auf dem Steuergerät.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Interaktionen:</strong>\n<ul class=\"fig-list\"><li>Client-interne Aktion (<code>set LogLevel</code>).\n</li><li>Externe Diagnose-/Netzwerkschnittstelle: Transport von DLT-Steuerungsnachrichten (<code>send Dlt control message</code>).\n</li><li>Modul-interne Filterverwaltung (<code>configuration of filter settings</code>).\n</li><li>Plattforminterne Benachrichtigungsschnittstelle vom DLT-Modul zur Applikation (<code>notify application about new filter setting</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Schritt 1 (<code>set LogLevel</code>):</strong> Am externen Laptop wählt der Anwender bzw. das Testwerkzeug die gewünschte Loglevel-Einstellung aus.\n</li><li><strong>Schritt 2 (<code>send Dlt control message</code>):</strong> Das Werkzeug überträgt eine Dlt-Steuernachricht an das Dlt-Modul der ECU.\n</li><li><strong>Schritt 3 (<code>configuration of filter settings</code>):</strong> Das Dlt-Modul (<code>DLT or ara::log</code>) aktualisiert seine internen Filtereinstellungen entsprechend der empfangenen Steuerungsnachricht.\n</li><li><strong>Schritt 4 (<code>notify application about new filter setting</code>):</strong> Das Dlt-Modul benachrichtigt die jeweilige Applikation über die geänderten Filterparameter, sodass das clientseitige/applikative Filtering wirksam wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation verdeutlicht die universelle Einsetzbarkeit des Protokolls für Classic AUTOSAR (DLT-Basissofortware) und Adaptive AUTOSAR (<code>ara::log</code>). Der Sequenzablauf betont die Vorkonfiguration im Tool (Schritt 1) sowie die gezielte Notifikation der Applikation (Schritt 4) über Steuernachrichten, um eine einheitliche Filtersteuerung über Plattformgrenzen hinweg sicherzustellen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3aeff100e9194779", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Interaktionsdiagramm für das Diagnostic Log and Trace Protokoll, gültig gleichermaßen für AUTOSAR Classic und Adaptive Platform. Das Diagramm illustriert den durchgängigen Ablauf einer dynamischen Laufzeitkonfiguration von Filter- und Loglevel-Parametern von einem externen DLT-Client hin zu ECU-Applikationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Laptop (DLT-Client / Tool):</strong> Externe Logging- und Diagnosekonsole zur Initiierung von Loglevel-Änderungen.\n</li><li><strong>ECU (Steuergerät):</strong> Beherbergt Applikationen und das zentrale Log-Subsystem.\n<ul class=\"fig-list\"><li><strong>Dlt module (DLT or ara::log):</strong> Zentrales Logging-Modul der Plattform (Classic DLT oder Adaptive ara::log), zuständig für die Verarbeitung von Dlt-Steuernachrichten und die Aktualisierung der Filterzustände.\n</li><li><strong>Application (dreifach dargestellt):</strong> Anwendungs- bzw. Prozessinstanzen auf dem Steuergerät.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Interaktionen:</strong>\n<ul class=\"fig-list\"><li>Client-interne Aktion (<code>set LogLevel</code>).\n</li><li>Externe Diagnose-/Netzwerkschnittstelle: Transport von DLT-Steuerungsnachrichten (<code>send Dlt control message</code>).\n</li><li>Modul-interne Filterverwaltung (<code>configuration of filter settings</code>).\n</li><li>Plattforminterne Benachrichtigungsschnittstelle vom DLT-Modul zur Applikation (<code>notify application about new filter setting</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Schritt 1 (<code>set LogLevel</code>):</strong> Am externen Laptop wählt der Anwender bzw. das Testwerkzeug die gewünschte Loglevel-Einstellung aus.\n</li><li><strong>Schritt 2 (<code>send Dlt control message</code>):</strong> Das Werkzeug überträgt eine Dlt-Steuernachricht an das Dlt-Modul der ECU.\n</li><li><strong>Schritt 3 (<code>configuration of filter settings</code>):</strong> Das Dlt-Modul (<code>DLT or ara::log</code>) aktualisiert seine internen Filtereinstellungen entsprechend der empfangenen Steuerungsnachricht.\n</li><li><strong>Schritt 4 (<code>notify application about new filter setting</code>):</strong> Das Dlt-Modul benachrichtigt die jeweilige Applikation über die geänderten Filterparameter, sodass das clientseitige/applikative Filtering wirksam wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation verdeutlicht die universelle Einsetzbarkeit des Protokolls für Classic AUTOSAR (DLT-Basissofortware) und Adaptive AUTOSAR (<code>ara::log</code>). Der Sequenzablauf betont die Vorkonfiguration im Tool (Schritt 1) sowie die gezielte Notifikation der Applikation (Schritt 4) über Steuernachrichten, um eine einheitliche Filtersteuerung über Plattformgrenzen hinweg sicherzustellen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-74697add00bd3b69", "to": "FIG-45bc866595cf9e4f", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-45bc866595cf9e4f", "to": "FIG-74697add00bd3b69", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-74697add00bd3b69", "to": "FIG-bb738c097eab79af", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Komponente <code>Runtime Environment</code>: Entfällt vollständig aus der ECU-Darstellung.\n</li><li>Komponente <code>DLT</code>: Umbenannt zu <code>Dlt module</code> mit dem Zusatz <code>(DLT or ara::log)</code>.\n</li><li>Laptop / Test-Client: Erhält einen expliziten Prozessschritt <code>1: set LogLevel</code>.\n</li><li>Kommunikationspfeil vom Laptop zum DLT-Modul: Schrittnummer von <code>1</code> auf <code>2</code> geändert; Beschriftung von <code>Set LogLevel</code> zu <code>send Dlt control message</code> präzisiert.\n</li><li>DLT-Modul-interner Schritt: Schrittnummer von <code>2</code> auf <code>3</code> geändert; Beschriftung <code>Configuration of Filter setting</code> angepasst zu <code>configuration of filter settings</code>.\n</li><li>Kommunikationspfeil vom DLT-Modul zur Applikation: Schrittnummer von <code>3</code> auf <code>4</code> geändert; Beschriftung <code>Inform Application about new filter setting</code> angepasst zu <code>notify application about new filter setting</code>; Bezeichner <code>LogMessage</code> an der Schnittstelle entfällt.\n</li></ul>"}, {"from": "FIG-bb738c097eab79af", "to": "FIG-3aeff100e9194779", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
